<script lang="ts">
import { defineComponent, type PropType } from 'vue'; import { addBookmark, deleteBookmark, listBookmarks, type Bookmark } from '../../api/reader'; import AppButton from '../../ui/components/AppButton.vue';
export default defineComponent({name:'ReaderBookmarksSheet',components:{AppButton},props:{bookId:{type:String,required:true},sourceUrl:{type:String,required:true},chapterIndex:{type:Number,required:true},capture:{type:Function as PropType<()=>Promise<{position:number;stateVersion:number}>>,required:true}},emits:['open','close'],data(){return{bookmarks:[] as Bookmark[],note:'',loading:true,busy:false,error:''}},async mounted(){try{this.bookmarks=await listBookmarks(this.bookId)}catch(cause){this.error=cause instanceof Error?cause.message:this.$t('reader.bookmarks.loadFailed')}finally{this.loading=false}},methods:{async submit(){if(this.busy)return;this.busy=true;this.error='';try{const location=await this.capture();const mark=await addBookmark(this.bookId,{id:crypto.randomUUID(),sourceUrl:this.sourceUrl,stateVersion:location.stateVersion,chapterIndex:this.chapterIndex,position:location.position,note:this.note});this.bookmarks=[mark,...this.bookmarks];this.note=''}catch(cause){this.error=cause instanceof Error?cause.message:this.$t('reader.bookmarks.saveFailed')}finally{this.busy=false}},async remove(mark:Bookmark){try{await deleteBookmark(this.bookId,mark.id);this.bookmarks=this.bookmarks.filter(item=>item.id!==mark.id)}catch(cause){this.error=cause instanceof Error?cause.message:this.$t('reader.bookmarks.deleteFailed')}}}});
</script>
<template><div class="overlay" @click.self="$emit('close')" @keydown.esc="$emit('close')"><section class="sheet" role="dialog" aria-modal="true" :aria-label="$t('reader.bookmarks.title')"><header><h2>{{ $t('reader.bookmarks.title') }}</h2><AppButton variant="quiet" @click="$emit('close')">{{ $t('reader.close') }}</AppButton></header><form @submit.prevent="submit"><textarea v-model="note" maxlength="1000" :placeholder="$t('reader.bookmarks.note')" /><AppButton type="submit" :busy="busy">{{ $t('reader.bookmarks.add') }}</AppButton></form><p v-if="error" class="error" role="status">{{ error }}</p><p v-if="loading">{{ $t('reader.bookmarks.loading') }}</p><p v-else-if="!bookmarks.length">{{ $t('reader.bookmarks.empty') }}</p><ul v-else><li v-for="mark in bookmarks" :key="mark.id" :class="{orphaned:mark.orphaned}"><div><strong>{{ mark.chapterTitle }}</strong><small>{{ $t('reader.bookmarks.position',{percent:Math.round(mark.position*100)}) }}<template v-if="mark.orphaned"> · {{ $t('reader.bookmarks.orphaned') }}</template></small><p v-if="mark.note">{{ mark.note }}</p></div><div class="actions"><AppButton variant="secondary" :disabled="mark.orphaned" @click="$emit('open',mark.chapterIndex,mark.position)">{{ $t('reader.bookmarks.open') }}</AppButton><AppButton variant="danger" @click="remove(mark)">{{ $t('reader.bookmarks.delete') }}</AppButton></div></li></ul></section></div></template>
<style scoped>.overlay{position:fixed;z-index:90;inset:0;display:flex;align-items:flex-end;justify-content:center;background:rgb(0 0 0/.38)}.sheet{width:min(46rem,100%);max-height:82dvh;overflow:auto;padding:1rem;border-radius:var(--radius-lg) var(--radius-lg) 0 0;background:var(--color-paper-raised);color:var(--color-ink)}header,.actions{display:flex;justify-content:space-between;align-items:center;gap:.5rem}h2{margin:0;font:700 1.2rem var(--font-literary)}form{display:grid;gap:.6rem;margin:1rem 0}textarea{min-height:5rem;resize:vertical;border:1px solid var(--color-border);border-radius:var(--radius-md);padding:.7rem}ul{list-style:none;display:grid;gap:.6rem;margin:0;padding:0}li{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:.8rem;padding:.75rem;border:1px solid var(--color-border);border-radius:var(--radius-md)}li strong,li small{display:block;overflow-wrap:anywhere}li small{margin-top:.2rem;color:var(--color-ink-muted)}li p{white-space:pre-wrap}.orphaned{opacity:.7}.error{color:var(--color-danger)}@media(max-width:36rem){li{grid-template-columns:1fr}.actions{justify-content:flex-start;flex-wrap:wrap}}</style>